/*
 * A032946  Numbers whose base-11 representation Sum_{i=0..m} d(i)*11^i has
 *          d(i)=0 for all odd i.
 * https://oeis.org/A032946
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) is the n‑th positive integer whose base‑11 representation
 *            contains zeros in all odd positions (counting from the most
 *            significant digit). The sequence is generated by enumerating the
 *            natural numbers in increasing order and selecting those that
 *            satisfy the digit condition
 * Range:     u8 n <= 42, u16 n <= 724, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <stddef.h>

/* Static cache to store the sequence terms across calls */
static seq_t *cache      = NULL;
static idx_t  cache_size = 0;
static idx_t  cache_cap  = 0;
static seq_t  next_value = 1;

/* Check whether x satisfies the digit rule */
static bool ok(seq_t x) {
    if (x == 0) return false;      /* exclude 0 */

    unsigned char digits[64];
    idx_t len = 0;
    seq_t temp = x;

    while (temp > (seq_t)0) {
        seq_t q = temp / (seq_t)11;
        seq_t r = temp % (seq_t)11;   /* 0 <= r < 11 */
        digits[len++] = (unsigned char)(int)r;
        temp = q;
    }

    /* Verify zeros at odd positions counted from the most significant digit */
    for (idx_t j = 0; j < len; ++j) {
        if ((j & 1) && digits[len - 1 - j] != 0)
            return false;
    }
    return true;
}

/* Ensure the cache contains at least 'n' terms */
static void ensure_cache(idx_t n) {
    while (cache_size < n) {
        /* Find the next qualifying number */
        while (!ok(next_value)) {
            ++next_value;
        }

        /* Grow cache if necessary */
        if (cache_size == cache_cap) {
            idx_t new_cap = cache_cap ? cache_cap * 2 : 64;
            cache = (seq_t *)realloc(cache, sizeof(seq_t) * new_cap);
            cache_cap = new_cap;
        }

        cache[cache_size++] = next_value;
        ++next_value;
    }
}

/* Public function required by the specification */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;   /* offset 1; behaviour for n<1 is irrelevant */

    ensure_cache(n);
    return cache[n - 1];
}
